class_name DialogueLogger
extends Node

const MAX_ENTRIES: int = 100

var _entries: Array[Dictionary] = []
var read_lines: Dictionary = {}


func add_entry(speaker: String, text: String) -> void:
	var entry_data := {
		"speaker": speaker,
		"text": text
	}
	_entries.append(entry_data)
	if _entries.size() > MAX_ENTRIES:
		_entries.pop_front()


func mark_line_as_read(chapter_path: String, line_index: int) -> void:
	var line_id: String = "%s#%d" % [chapter_path, line_index]
	read_lines[line_id] = true


func is_line_read(chapter_path: String, line_index: int) -> bool:
	var line_id: String = "%s#%d" % [chapter_path, line_index]
	return read_lines.has(line_id)


func export_history_as_text() -> String:
	if _entries.is_empty():
		return ""
	var lines: Array[String] = []
	for entry in _entries:
		var speaker: String = String(entry.get("speaker", ""))
		var text: String = String(entry.get("text", ""))
		if speaker.is_empty():
			lines.append(text)
		else:
			lines.append("%s: %s" % [speaker, text])
	return "\n".join(lines)


func get_unread_count_in_chapter(chapter_path: String, total_lines: int) -> int:
	var count := 0
	for i in range(total_lines):
		if not is_line_read(chapter_path, i):
			count += 1
	return count


func can_start_skip(chapter_path: String, start_line: int) -> bool:
	return is_line_read(chapter_path, start_line)
